// Some portions generated by Claude
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * End-to-end guards for {@code SameTermFilterOptimizer}: a {@code sameTerm} filter whose variable is bound by an
 * enclosing scope (the solution substituted into an EXISTS / NOT EXISTS body, or the left side of a LATERAL) must not
 * be proven empty or inlined based on the filter argument alone.
 */
public class SameTermExistsScopeTest {

	private static final String PREFIX = "PREFIX : <http://ex/>\n";

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	private void load(String trig) throws Exception {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader("@prefix : <http://ex/> .\n" + trig), "http://ex/", RDFFormat.TRIG);
		}
	}

	private List<String> rows(String query, String... vars) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			TupleQuery tupleQuery = conn.prepareTupleQuery(PREFIX + query);
			List<String> result = new ArrayList<>();
			try (TupleQueryResult res = tupleQuery.evaluate()) {
				for (BindingSet bs : res) {
					StringBuilder sb = new StringBuilder();
					for (String var : vars) {
						sb.append(var).append('=').append(bs.getValue(var)).append(' ');
					}
					result.add(sb.toString().trim());
				}
			}
			return result.stream().sorted().collect(Collectors.toList());
		}
	}

	@Test
	public void sameTermOnOuterVariableInsideExistsKeepsMatchingRow() throws Exception {
		load(":s1 :p :v1 . :s1 :q :o1 .\n");
		String query = "SELECT ?s WHERE { ?s :p ?x FILTER EXISTS { ?s :q ?o FILTER(sameTerm(?x, :v1)) } }";
		assertEquals(List.of("s=http://ex/s1"), rows(query, "s"));
	}

	@Test
	public void sameTermOnOuterVariableInsideNotExistsDropsMatchingRowOnly() throws Exception {
		load(":s1 :p :v1 . :s1 :q :o1 .\n:s2 :p :v2 . :s2 :q :o2 .\n");
		String query = "SELECT ?s WHERE { ?s :p ?x FILTER NOT EXISTS { ?s :q ?o FILTER(sameTerm(?x, :v1)) } }";
		// s1: body matches (x = :v1) -> dropped; s2: sameTerm(:v2, :v1) is false -> body empty -> kept
		assertEquals(List.of("s=http://ex/s2"), rows(query, "s"));
	}

	@Test
	public void sameTermOnOuterVariableInsideLateralKeepsMatchingRow() throws Exception {
		load(":s1 :p :v1 . :s1 :q :o1 .\n:s2 :p :v2 . :s2 :q :o2 .\n");
		String query = "SELECT ?s ?o WHERE { ?s :p ?x LATERAL { ?s :q ?o FILTER(sameTerm(?x, :v1)) } }";
		assertEquals(List.of("s=http://ex/s1 o=http://ex/o1"), rows(query, "s", "o"));
	}

	@Test
	public void sameTermOnOuterVariableInsideNestedGroupInExistsKeepsMatchingRow() throws Exception {
		load(":s1 :p :v1 . :s1 :q :o1 .\n:s2 :p :v2 . :s2 :q :o2 .\n");
		String query = "SELECT ?s WHERE { ?s :p ?x FILTER EXISTS { { ?s :q ?o FILTER(sameTerm(?x, :v1)) } } }";
		assertEquals(List.of("s=http://ex/s1"), rows(query, "s"));
	}

	@Test
	public void sameTermOnVariableSharedWithOuterScopeIsNotInlinedInsideExists() throws Exception {
		// the inner ?x is the outer ?x (EXISTS substitutes the outer solution); inlining :v1 into the body would
		// ignore the outer value :v2 and wrongly accept s1
		load(":s1 :p :v2 . :s1 :q :v1 .\n:s2 :p :v1 . :s2 :q :v1 .\n");
		String query = "SELECT ?s WHERE { ?s :p ?x FILTER EXISTS { ?s :q ?x FILTER(sameTerm(?x, :v1)) } }";
		assertEquals(List.of("s=http://ex/s2"), rows(query, "s"));
	}

	@Test
	public void sameTermOnVariableBoundNowhereStillYieldsNoRows() throws Exception {
		load(":s1 :p :v1 .\n");
		String query = "SELECT ?s WHERE { ?s :p ?x FILTER(sameTerm(?y, :v1)) }";
		assertEquals(List.of(), rows(query, "s"));
	}

	/** The renamed variable is possibly bound by a VALUES row with UNDEF; the rows of the VALUES cannot be renamed. */
	@Test
	public void sameTermRenamingIsDeclinedWhenValuesPossiblyBindsTheRenamedVariable() throws Exception {
		load(":s1 :p :v . :s1 :q :v .\n");
		String query = "SELECT ?s ?x ?y WHERE { VALUES ?y { UNDEF :w } ?s :p ?x . ?s :q ?y FILTER(sameTerm(?x, ?y)) }";
		// only the UNDEF row joins (y = :v from ?s :q ?y); the :w row has no ?s :q :w match
		assertEquals(List.of("s=http://ex/s1 x=http://ex/v y=http://ex/v"), rows(query, "s", "x", "y"));
	}

	/**
	 * The outer ?x is also bound inside the body, so it is assured there; renaming it away (x := ?o) would let the
	 * body's Extension overwrite the substituted outer value and wrongly accept s1 (no :r :a triple exists).
	 */
	@Test
	public void sameTermBetweenInnerAndOuterVariableInsideExistsIsNotRenamedAway() throws Exception {
		load(":s1 :p :a . :s1 :q :b . :s1 :r :b .\n");
		String query = "SELECT ?s WHERE { ?s :p ?x FILTER EXISTS { ?s :q ?o . ?s :r ?x FILTER(sameTerm(?o, ?x)) } }";
		assertEquals(List.of(), rows(query, "s"));
	}

	@Test
	public void sameTermBetweenOuterAndInnerVariableInsideExistsIsNotRenamedAway() throws Exception {
		load(":s1 :p :a . :s1 :q :b . :s1 :r :b .\n");
		String query = "SELECT ?s WHERE { ?s :p ?x FILTER EXISTS { ?s :q ?o . ?s :r ?x FILTER(sameTerm(?x, ?o)) } }";
		assertEquals(List.of(), rows(query, "s"));
	}

	@Test
	public void sameTermBetweenInnerAndOuterVariableInsideNotExistsIsNotRenamedAway() throws Exception {
		load(":s1 :p :a . :s1 :q :b . :s1 :r :b .\n");
		String query = "SELECT ?s WHERE { ?s :p ?x FILTER NOT EXISTS { ?s :q ?o . ?s :r ?x FILTER(sameTerm(?o, ?x)) } }";
		assertEquals(List.of("s=http://ex/s1"), rows(query, "s"));
	}

	@Test
	public void sameTermBetweenTwoOuterVariablesInsideExistsIsKept() throws Exception {
		load(":s1 :p :a . :s1 :t :a . :s1 :q :a . :s1 :r :a .\n:s2 :p :a . :s2 :t :b . :s2 :q :a . :s2 :r :a .\n");
		String query = "SELECT ?s WHERE { ?s :p ?x . ?s :t ?y"
				+ " FILTER EXISTS { ?s :q ?x . ?s :r ?y FILTER(sameTerm(?x, ?y)) } }";
		// s2: x = :a, y = :b -> sameTerm false -> excluded; renaming ?y to ?x would accept it (s2 :r :a exists)
		assertEquals(List.of("s=http://ex/s1"), rows(query, "s"));
	}

	@Test
	public void sameTermBetweenInnerAndOuterVariableInsideLateralIsNotRenamedAway() throws Exception {
		load(":s1 :p :a . :s1 :q :b . :s1 :r :b .\n");
		String query = "SELECT ?s ?o WHERE { ?s :p ?x LATERAL { ?s :q ?o . ?s :r ?x FILTER(sameTerm(?o, ?x)) } }";
		assertEquals(List.of(), rows(query, "s", "o"));
	}

	/** Regression guard: renaming the inner variable into the outer one is sound and keeps the matching row. */
	@Test
	public void sameTermBetweenInnerAndOuterVariableInsideExistsKeepsMatchingRow() throws Exception {
		load(":s1 :p :a . :s1 :q :a . :s1 :r :a .\n:s2 :p :a . :s2 :q :b . :s2 :r :a .\n");
		String query = "SELECT ?s WHERE { ?s :p ?x FILTER EXISTS { ?s :q ?o . ?s :r ?x FILTER(sameTerm(?o, ?x)) } }";
		assertEquals(List.of("s=http://ex/s1"), rows(query, "s"));
	}
}
